import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Mengatur kontras hanya butuh beberapa menit. Anda mengunggah foto, menggeser slider, memeriksa highlight dan bayangan, lalu mengunduh versi yang lebih tegas.</p>\n<p>Panduan cara ini memandu seluruh proses langkah demi langkah. Di dalamnya ada slider, preset cepat, mode perbandingan, dan pengaturan ekspor yang menjaga hasilnya tetap terlihat alami.</p>\n<p>Di akhir panduan, Anda bisa memperbaiki lanskap yang datar, melembutkan potret yang kasar, atau mempertajam tangkapan layar yang kusam di perangkat apa pun. Simpan foto aslinya sampai Anda memeriksa hasilnya.</p>\n<h2 id=\"before-you-start\">Sebelum Memulai: Diagnosis Fotonya</h2>\n<p>Lihat foto sebelum Anda membuka alat. Apakah fotonya datar dan abu-abu, kasar dengan bayangan yang dalam, atau sebarannya sudah tepat? Jawabannya memberi tahu ke arah mana slider harus digerakkan.</p>\n<p>Foto yang datar butuh dorongan positif 10 sampai 20 persen. Foto yang kasar butuh perubahan negatif 10 sampai 20 persen untuk melembutkan ujung-ujungnya.</p>\n<p>Periksa apakah fotonya juga terlalu gelap atau terlalu terang. Foto yang gelap sekaligus datar butuh kecerahan dulu, karena kontras saja tidak bisa memperbaiki tingkatnya.</p>\n<p>Buka <a href=\"/id/sesuaikan-kontras-gambar/\">Editor Kontras Gambar</a> di peramban Anda. Semuanya berjalan secara lokal, jadi foto Anda tidak pernah diunggah ke server.</p>\n<h2 id=\"step-by-step\">Mengatur Kontras dalam Lima Langkah</h2>\n<p>Prosesnya sama untuk foto, tangkapan layar, atau dokumen hasil pindaian. Unggah, sesuaikan, bandingkan, ekspor, lalu verifikasi hasil unduhannya.</p>\n<p>Luangkan waktu untuk slidernya. Perubahan kecil memberi perbedaan besar, dan pratinjau menunjukkan dengan tepat kapan foto terlihat pas.</p>\n<ol>\n<li>Unggah gambar dengan menyeretnya ke area unggah, memilihnya dari perangkat, atau menempel tangkapan layar dengan Ctrl+V.</li>\n<li>Geser slider Tingkat Kontras ke kanan untuk menaikkan kontras atau ke kiri untuk menurunkannya, sambil memperhatikan pratinjau langsung.</li>\n<li>Coba preset cepat untuk pengujian sekali klik, lalu sesuaikan dengan slider jika hasilnya sudah dekat tetapi belum tepat.</li>\n<li>Gunakan mode perbandingan untuk memeriksa highlight dan bayangan terhadap foto asli sebelum mengunduh.</li>\n<li>Pilih format ekspor dan kualitasnya, lalu klik Unduh untuk menyimpan gambar yang sudah disesuaikan.</li>\n</ol>\n<p>Buka file yang sudah diunduh sekali sebelum Anda menggunakannya. Pastikan foto terlihat tegas tanpa kehilangan detail di area terang atau gelap.</p>\n<h2 id=\"using-the-slider\">Menggunakan Slider Kontras</h2>\n<p>Slider bergerak dari nilai negatif ke positif, dengan nol berarti tanpa perubahan. Menggesernya ke kanan menaikkan kontras, dan menggesernya ke kiri menurunkannya.</p>\n<p>Geser perlahan dan perhatikan pratinjaunya. Pembaruan langsung menunjukkan dengan tepat bagaimana gambar merespons, jadi Anda bisa berhenti saat foto terlihat pas.</p>\n<p>Perubahan kecil lebih baik daripada perubahan besar. Perubahan 10 sampai 20 persen sering sudah cukup, dan perubahan yang lebih besar cepat memotong highlight dan menghancurkan bayangan.</p>\n<p>Alat ini menampilkan foto Anda pada plus 20 persen tepat setelah diunggah. Titik awal itu memberi gambaran langsung tentang seperti apa dorongan kontras sedang itu.</p>\n<h2 id=\"using-quick-presets\">Menggunakan Preset Cepat</h2>\n<p>Alat ini menyertakan preset cepat yang menerapkan nilai kontras umum dalam satu klik. Preset adalah cara cepat menguji berbagai tingkat tanpa menggeser slider.</p>\n<p>Klik preset dan lihat pratinjaunya. Jika hasilnya sudah dekat tetapi belum tepat, sesuaikan dengan slider dari titik itu.</p>\n<p>Gunakan preset untuk membandingkan pilihan dengan cepat. Preset plus 10 persen di samping preset plus 30 persen menunjukkan seberapa banyak kontras yang bisa ditahan foto.</p>\n<p>Untuk sekumpulan foto serupa, preset yang sama menjaga hasilnya tetap konsisten. Sekumpulan lanskap berkabut yang didorong dengan jumlah yang sama akan terlihat seperti satu rangkaian.</p>\n<h2 id=\"using-compare-modes\">Menggunakan Mode Perbandingan</h2>\n<p>Mode perbandingan menampilkan foto asli dan versi yang sudah diedit secara bersamaan. Tampilan Sesudah menunjukkan gambar yang kontrasnya didorong, dan tampilan Sebelum menunjukkan foto asli.</p>\n<p>Perbandingan Terbelah paling berguna untuk pekerjaan kontras. Mode ini menampilkan kedua versi berdampingan, jadi Anda bisa melihat dengan tepat bayangan mana yang makin dalam dan highlight mana yang makin terang.</p>\n<p>Perbandingan Layar Penuh memberi tampilan terbesar. Mode ini cara terbaik menilai edit kontras, karena gambar ukuran penuh menampilkan pemotongan yang disembunyikan pratinjau kecil.</p>\n<p>Periksa tampilan perbandingan sebelum setiap unduhan. Sekilas pandang bisa menangkap highlight yang terpotong dan bayangan yang hancur, yang mungkin disembunyikan pratinjau kecil.</p>\n<h2 id=\"boosting-a-flat-photo\">Mendorong Foto yang Datar</h2>\n<p>Unggah foto yang datar itu dan geser slider ke plus 15 persen. Periksa pratinjaunya: bayangan sebaiknya makin dalam, highlight sebaiknya makin terang, dan gambar terasa kokoh.</p>\n<p>Jika foto masih datar, naikkan slider sedikit demi sedikit, 5 persen setiap kali. Setiap langkah menambah sedikit ketegasan, dan pratinjau menunjukkan kapan harus berhenti.</p>\n<p>Perhatikan highlight selama Anda menaikkan. Awan, kemeja putih, dan kulit yang terang akan terpotong paling dulu, berubah menjadi bercak putih polos tanpa detail.</p>\n<p>Jika foto terlihat kasar setelah didorong, turunkan slider 5 persen. Sedikit penurunan sering mengembalikan detail tanpa membuat foto datar lagi.</p>\n<h2 id=\"softening-a-harsh-photo\">Melembutkan Foto yang Kasar</h2>\n<p>Geser slider ke kiri untuk foto yang diambil di bawah matahari tengah hari yang terik. Nilai negatif seperti minus 10 atau minus 20 persen melembutkan bayangan kuat di wajah.</p>\n<p>Periksa wajah saat Anda melembutkan. Bayangan sebaiknya memudar menjadi tampilan yang lebih lembut, sedangkan bentuk wajah keseluruhannya tetap jelas dan tegas.</p>\n<p>Kontras negatif juga cocok untuk lanskap yang lembut dan melamun. Pemandangan pagi yang berkabut dengan kontras rendah terasa tenang dan sunyi, dan itu cocok dengan suasana fotonya.</p>\n<p>Jangan berlebihan. Foto dengan kontras yang terlalu sedikit terlihat abu-abu dan tidak bernyawa, seolah-olah diambil menembus kabut, bahkan pada hari yang cerah.</p>\n<h2 id=\"fixing-a-screenshot\">Memperbaiki Tangkapan Layar yang Kusam</h2>\n<p>Tempel tangkapan layar langsung dengan Ctrl+V untuk melewati langkah menyimpan. Gambar langsung muncul di editor dan siap disesuaikan.</p>\n<p>Naikkan kontras sampai teksnya gelap dan latarnya putih. Dokumen dengan teks hitam yang kuat di atas latar putih bersih mudah dibaca dan dicetak.</p>\n<p>Waspadai noise di latar. Pindaian yang dikontraskan kuat bisa menampilkan bintik dan artefak, terutama pada JPEG yang sudah dikompres.</p>\n<p>Ekspor tangkapan layar sebagai PNG. Format lossless ini menjaga teks kecil tetap tajam, dan itu penting saat tangkapan layar menampilkan pengaturan atau pesan galat.</p>\n<h2 id=\"checking-shadows-highlights\">Memeriksa Bayangan dan Highlight</h2>\n<p>Setelah setiap perubahan kontras, periksa bagian paling gelap dan paling terang pada gambar secara terpisah. Bayangan hancur paling dulu di bawah dorongan, dan highlight terpotong paling dulu di bawah perubahan yang sama.</p>\n<p>Perbesar area bayangan dan pastikan masih menampilkan detail. Mantel, pohon, atau sudut gelap sebaiknya punya tekstur yang terlihat, bukan bercak hitam pekat.</p>\n<p>Perbesar area highlight dan pastikan masih menampilkan detail. Awan, kemeja putih, atau dahi yang terang sebaiknya punya bentuk yang terlihat, bukan putih polos.</p>\n<p>Jika salah satu ujung kehilangan detail, turunkan slider 5 persen lalu periksa lagi. Sedikit penurunan biasanya mengembalikan detail tanpa menghilangkan ketegasannya.</p>\n<h2 id=\"previewing\">Memeriksa Pratinjau Sebelum Mengunduh</h2>\n<p>Selalu periksa pratinjau sebelum mengunduh. Pastikan foto terlihat tegas, tidak ada area terang yang berubah putih, dan tidak ada area gelap yang berubah hitam.</p>\n<p>Gunakan tampilan perbandingan terbelah untuk memeriksa perubahan. Tampilan ini menunjukkan foto asli dan versi yang sudah diedit berdampingan, jadi Anda bisa melihat dengan tepat apa yang dilakukan kontras.</p>\n<p>Perbesar area terang dan gelap pada ukuran penuh. Langit atau bayangan yang terlihat bagus di pratinjau kecil bisa terpotong atau hancur saat dilihat dalam ukuran besar.</p>\n<p>Jika hasilnya terlihat kasar, turunkan slider 5 persen lalu periksa lagi. Sedikit penurunan sering mengembalikan detail tanpa membuat foto datar lagi.</p>\n<h2 id=\"choosing-export-format\">Memilih Format Ekspor</h2>\n<p>Pilih JPG untuk foto yang akan dibagikan. Format ini menjaga ukuran file tetap kecil dan bisa dipakai di mana saja, dan kualitas tinggi menjaga foto yang sudah diedit kontrasnya tetap terlihat bersih.</p>\n<p>Pilih PNG untuk tangkapan layar dan grafis berisi teks. PNG lossless, jadi tepi huruf tetap tajam, dan format ini menjaga transparansi saat dibutuhkan.</p>\n<p>Pilih WebP saat Anda ingin file kecil dengan kualitas bagus. Format ini bekerja baik untuk gambar web, meskipun beberapa sistem lama masih menolaknya.</p>\n<p>Ingat bahwa slider kualitas tersembunyi untuk PNG, karena PNG lossless dan tidak punya pengaturan kualitas. Itu perilaku normal, bukan masalah pada alatnya.</p>\n<h2 id=\"adjusting-on-mobile\">Mengatur Kontras di Ponsel atau Tablet</h2>\n<p>Alat ini bekerja di layar sentuh, jadi Anda bisa memperbaiki foto yang datar langsung di ponsel yang memotretnya. Unggah dari galeri, geser slider dengan jari, lalu unduh hasilnya.</p>\n<p>Menggeser slider dengan jari kurang presisi daripada dengan tetikus. Gunakan preset cepat untuk nilai yang tepat, lalu sesuaikan dengan geseran kecil.</p>\n<p>Periksa pratinjau dalam ukuran penuh sebelum mengunduh. Perubahan kontras yang terlihat bagus di layar ponsel kecil bisa terlalu kuat saat dilihat di komputer.</p>\n<p>File yang diunduh tersimpan di folder unduhan biasa Anda. Dari sana, Anda bisa langsung membagikan foto yang sudah diedit ke aplikasi chat, email, atau postingan media sosial.</p>\n<h2 id=\"troubleshooting\">Mengatasi Masalah Umum pada Kontras</h2>\n<p>Jika foto terlihat kasar, slidernya terlalu tinggi. Turunkan sedikit demi sedikit sampai kulit, langit, dan area bayangan menampilkan tekstur lagi.</p>\n<p>Jika foto masih datar setelah didorong, foto aslinya mungkin terlalu berkabut untuk diselamatkan. Foto yang diambil menembus kabut tebal tidak bisa mendapat detail yang memang tidak pernah tertangkap.</p>\n<p>Jika highlight-nya terpotong, turunkan slider dan periksa area terang pada ukuran penuh. Sedikit penurunan biasanya mengembalikan detail awan atau kulit.</p>\n<p>Jika pratinjau terlihat berbeda dari hasil unduhan, periksa format ekspor dan kualitasnya. Pengaturan kualitas JPG yang rendah bisa melembutkan seluruh gambar, termasuk tepi kontrasnya.</p>\n<h2 id=\"contrast-plus-brightness\">Kontras Ditambah Kecerahan: Pasangan yang Umum</h2>\n<p>Foto yang sekaligus gelap dan datar butuh kecerahan dan kontras bersama-sama. Cerahkan dulu untuk mengangkat tingkat keseluruhannya, lalu tambahkan kontras untuk mengembalikan kedalaman.</p>\n<p>Gunakan <a href=\"/id/editor-kecerahan-gambar/\">Editor Kecerahan Gambar</a> sebelum menambah kontras saat gambarnya gelap. Dorongan kontras pada foto gelap hanya memperdalam bayangannya.</p>\n<p>Lakukan langkahnya secara berurutan, kecerahan dulu, baru kontras. Membaliknya bisa membuat penyesuaian kontras lebih sulit dinilai, karena gambarnya masih gelap.</p>\n<p>Periksa tampilan perbandingan setelah setiap langkah. Tampilan terbelah menunjukkan dengan tepat apa yang dilakukan setiap penyesuaian, jadi Anda bisa berhenti saat foto terlihat pas.</p>\n<h2 id=\"saving-settings\">Menyimpan Pengaturan untuk Lain Kali</h2>\n<p>Catat nilai kontras yang berhasil untuk sekumpulan foto serupa. Catatan singkat, misalnya lanskap berkabut plus 20 persen, menghemat waktu Anda dari menebak-nebak lain kali.</p>\n<p>Untuk sekumpulan foto yang diambil dalam cahaya yang sama, gunakan nilai yang sama untuk semuanya. Kontras yang konsisten di seluruh set terlihat profesional, sedangkan nilai yang bercampur terlihat acak.</p>\n<p>Simpan file aslinya. Nilai kontras yang cocok untuk satu foto mungkin tidak cocok untuk foto lain, dan file asli memungkinkan Anda mencoba tingkat yang berbeda tanpa kerusakan tambahan.</p>\n<p>Tinjau catatan Anda sesekali. Seiring kamera dan pencahayaan Anda membaik, nilai kontras yang dibutuhkan akan berubah, dan catatan lama bisa menyesatkan.</p>\n<h2 id=\"quick-tips\">Tips Cepat untuk Kontras yang Lebih Bagus</h2>\n<p>Sesuaikan sedikit demi sedikit. Perubahan 5 persen setiap kali memberi Anda kendali, sedangkan lompatan besar bisa melewati nilai yang tepat sebelum Anda sadar.</p>\n<p>Periksa ujung-ujungnya, bukan hanya bagian tengah. Foto disebut terlalu berkontras saat highlight terpotong atau bayangan hancur, meskipun midtone-nya terlihat bagus.</p>\n<p>Gunakan tampilan perbandingan setiap kali. Sekilas pandang pada foto asli di samping hasil edit menangkap kesalahan yang disembunyikan pratinjau kecil.</p>\n<p>Simpan foto asli tanpa edit. Setelah perubahan kontras diratakan ke dalam file ekspor, perubahan itu tidak bisa dibatalkan dari file tersebut.</p>\n<h2 id=\"contrast-for-product-photo\">Menambah Kontras pada Foto Produk</h2>\n<p>Foto produk butuh kontras yang jelas supaya barang menonjol dari latarnya. Foto produk yang datar terlihat kusam, sedangkan yang tegas menarik mata ke barangnya.</p>\n<p>Gunakan dorongan sedang 10 sampai 20 persen untuk kebanyakan produk. Barang sebaiknya terlihat kokoh dan jelas bentuknya, dengan tepi yang tegas terhadap latarnya.</p>\n<p>Perhatikan warna produk saat Anda menaikkan kontras. Dorongan yang terlalu kuat bisa membuat warnanya terlihat kasar, jadi periksa barangnya sendiri, bukan hanya latarnya.</p>\n<p>Jaga kontras tetap konsisten di seluruh katalog. Toko dengan tingkat kontras yang sama terlihat rapi dan tepercaya, sedangkan tingkat yang bercampur terlihat ceroboh.</p>\n<p>Foto produk untuk marketplace adalah contoh yang bagus. Kontras 10 sampai 20 persen membuat barang menonjol dari latar putih, dan pembeli bisa melihat detailnya tanpa memperbesar gambar.</p>\n<p>Untuk foto sebelum dan sesudah, kontras yang konsisten sangat penting. Jika foto sesudahnya lebih berkontras daripada sebelumnya, perbandingannya menjadi tidak adil dan menyesatkan.</p>\n<p>Foto langit malam dengan lampu kota juga butuh perhatian khusus. Dorongan kontras yang terlalu besar membuat lampu menjadi putih polos, sedangkan yang sedang menjaga kilau lampu tetap terlihat.</p>\n<p>Saat mengedit banyak foto dari satu acara, gunakan nilai yang sama untuk semuanya. Konsistensi membuat album terasa seperti satu cerita, sedangkan nilai yang bercampur membuat album terasa berantakan.</p>\n<p>Jika Anda memakai filter setelah mengatur kontras, periksa lagi highlightnya. Filter bisa menambah kontras lagi, dan gabungan keduanya bisa memotong detail yang sebelumnya masih aman.</p>\n<p>Terakhir, jangan menilai kontras hanya dari thumbnail kecil. Buka foto pada ukuran penuh, karena pemotongan highlight dan bayangan yang hancur baru terlihat jelas pada ukuran besar.</p>\n<p>Foto arsitektur malam hari juga bisa diuji dengan kontras. Lampu gedung yang terang dan langit yang gelap memberi dua ujung yang jelas, dan sedikit dorongan membuat keduanya makin tegas tanpa menghilangkan detail.</p>\n<p>Untuk perbandingannya, baca <a href=\"/id/blog/kecerahan-vs-eksposur-vs-kontras/\">Kecerahan vs Eksposur vs Kontras: Dasar-Dasar Editing</a>. Untuk gambaran lengkapnya, lihat <a href=\"/id/blog/panduan-mengatur-kontras-gambar/\">Editor Kontras Gambar: Panduan Lengkap</a>, dan untuk memperbaiki foto gelap sebelum menambah kontras, coba <a href=\"/id/editor-kecerahan-gambar/\">Editor Kecerahan Gambar</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Bagaimana cara menambah kontras foto di ponsel?","answer":"Buka Editor Kontras Gambar di peramban ponsel, unggah foto dari galeri, lalu geser slider ke kanan dengan jari Anda. Gunakan preset cepat untuk nilai yang tepat, periksa tampilan perbandingan, lalu unduh hasilnya."},{"question":"Nilai kontras berapa yang sebaiknya dipakai untuk lanskap berkabut?","answer":"Mulailah dari plus 15 sampai 20 persen dan periksa langitnya. Kabut meratakan rentang nada, jadi dorongan sedang mengembalikan kedalamannya. Berhentilah sebelum awan berubah menjadi putih polos, dan turunkan slider jika highlight terpotong."},{"question":"Bisakah saya mengurangi kontras untuk melembutkan potret yang kasar?","answer":"Bisa. Geser slider ke kiri ke nilai negatif, misalnya minus 10 atau minus 20 persen. Kontras negatif melembutkan bayangan kuat di wajah tanpa menghilangkan bentuknya. Periksa kulitnya supaya tetap jelas dan tidak berubah abu-abu."},{"question":"Kenapa highlight foto saya berubah putih setelah menambah kontras?","answer":"Kontrasnya didorong terlalu jauh, sehingga area paling terang terpotong menjadi putih murni. Turunkan slider sedikit demi sedikit sampai awan, kulit, dan permukaan putih menampilkan detail lagi. Dorongan 10 sampai 20 persen biasanya sudah cukup."},{"question":"Sebaiknya saya mengatur kontras dulu atau kecerahan dulu?","answer":"Kecerahan dulu, baru kontras. Kecerahan menetapkan tingkat keseluruhan, dan kontras menyempurnakan sebaran di sekitar tingkat itu. Foto gelap butuh dicerahkan sebelum dikontraskan, karena kontras saja tidak bisa memperbaiki tingkatnya."},{"question":"Bisakah saya membatalkan perubahan kontras setelah mengunduh?","answer":"Tidak dari file yang sudah diunduh, karena perubahannya sudah diratakan ke dalam file ekspor. Simpan foto aslinya supaya Anda bisa mencoba tingkat kontras yang berbeda. Di dalam alat, gunakan opsi reset untuk kembali ke nol sebelum mengunduh."}];
